import{_ as e,c as t,o as a,a4 as s}from"./chunks/framework.ttppV29E.js";const f=JSON.parse('{"title":"Agentic Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/agentic.md","filePath":"docs/tasks/agentic.md","lastUpdated":1795163079000}'),n={name:"docs/tasks/agentic.md"},o=s('<h1 id="agentic-tasks" tabindex="-1">Agentic Tasks <a class="header-anchor" href="#agentic-tasks" aria-label="Permalink to &quot;Agentic Tasks&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p>Agentic tasks will be released in version 2.42.0, planned for release on 21/10/2026.</p></div><p>An agentic task sends a request to an AI agent configured in AireGlu for your tenant, and stores the agent&#39;s response so later tasks can use it. Like other automated tasks, it starts as soon as it&#39;s created and finishes as <code>Completed</code> or <code>Failed</code>. Agentic tasks appear on the Tasks page alongside other task types.</p><p>Agentic tasks must be enabled for each tenant. Contact <a href="mailto:support@airelogic.com" target="_blank" rel="noreferrer">support@airelogic.com</a> to have them enabled for yours. Until then, the Agentic task type isn&#39;t available in the designer, and agentic tasks aren&#39;t created when triggered.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Agent</td><td>The AireGlu agent to use. Leave it on <code>Auto</code> to let AireFlow choose one from your tenant&#39;s agents.</td></tr><tr><td>Capability</td><td>The capability to use on the selected agent. Leave it on <code>Auto</code> to let AireFlow choose. You can only pin a capability if you&#39;ve also pinned an agent.</td></tr><tr><td>Intent</td><td>Shown when Agent or Capability is on <code>Auto</code>. Describes what the task should do, such as <code>Book an appointment for the patient</code>, and is used to choose the agent and capability.</td></tr><tr><td>Input</td><td>Key-value pairs sent to the agent. Values can use <a href="./../workflows/mapping.html">XPath and Liquid</a>.</td></tr><tr><td>Output</td><td>The fields the agent must return. Each value is optional, and can use XPath and Liquid.</td></tr><tr><td>Due date and expiry</td><td>As for other tasks. See <a href="./task-due-date.html">Task Due Date</a> and <a href="./expiry.html">Task Expiry</a>.</td></tr></tbody></table><p>Input and Output keys must start with a letter and can only contain letters, numbers, underscores and dashes, such as <code>appointmentDate</code> or <code>appointment-date</code>. Keys are case-insensitive, so <code>Date</code> and <code>date</code> count as duplicates.</p><p>Pin both Agent and Capability when you know which one the task needs, and use <code>Auto</code> when the right one depends on the request.</p><h2 id="output-fields" tabindex="-1">Output fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output fields&quot;">​</a></h2><p>If you set Output fields, AireFlow keeps asking the agent until every field has a value, up to 5 times. Each request tells the agent which fields are still missing.</p><ul><li>If an Output field&#39;s value isn&#39;t empty once mapped, it&#39;s used for that field and the agent isn&#39;t asked for it.</li><li>An Output field with the same key as an Input value takes the Input value.</li><li>If a request doesn&#39;t fill in any more fields, AireFlow stops early rather than repeating it.</li></ul><p>The task fails if any Output field is still missing at the end. The workflow logs show which fields were missing.</p><p>Without Output fields, the agent is called once and its response is stored as it is.</p><h2 id="using-the-agent-s-response" tabindex="-1">Using the agent&#39;s response <a class="header-anchor" href="#using-the-agent-s-response" aria-label="Permalink to &quot;Using the agent&#39;s response&quot;">​</a></h2><p>When the task completes, its emitted context automatically includes an <code>agentic</code> element, so tasks triggered by it can use the response:</p><table><thead><tr><th>Expression</th><th>Value</th></tr></thead><tbody><tr><td><code>{{ context.agentic.data.fieldName }}</code></td><td>An Output field, or a field from the agent&#39;s JSON response</td></tr><tr><td><code>{{ context.agentic.summary }}</code></td><td>The agent&#39;s text response, if it returned one</td></tr><tr><td><code>{{ context.agentic.dataJson }}</code></td><td>All of the response fields as a JSON string</td></tr><tr><td><code>{{ context.agentic.routing.agentName }}</code>, <code>{{ context.agentic.routing.capabilityId }}</code></td><td>The agent and capability that were used</td></tr></tbody></table><p>For example, with an Output field of <code>appointmentDate</code>, a later HTTP task could send:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ &quot;appointmentDate&quot;: &quot;{{ context.agentic.data.appointmentDate }}&quot; }</span></span></code></pre></div><p>The response is also kept in the task&#39;s state, under <code>agentic.output</code>, and is viewable via AireFlow&#39;s Tasks page.</p><h2 id="retry-on-failure" tabindex="-1">Retry on failure <a class="header-anchor" href="#retry-on-failure" aria-label="Permalink to &quot;Retry on failure&quot;">​</a></h2><p><code>Retry on Failure</code> works the same as for other automated tasks. If it&#39;s set to <code>Yes</code> and the task fails, the whole task is run again a number of times before it&#39;s left as <code>Failed</code>. This is separate from the repeated requests used to fill in Output fields.</p>',21),i=[o];function d(r,l,c,h,u,p){return a(),t("div",null,i)}const k=e(n,[["render",d]]);export{f as __pageData,k as default};
